mapper.select:
SELECT id, student_id AS studentId, check_in_id AS checkInId, exception_type AS exceptionType, status, handler_id AS handlerId, handler_note AS handlerNote, handled_at AS handledAt, created_at AS createdAt, updated_at AS updatedAt FROM check_in_exception WHERE 1=1
AND student_id = #{studentId}
AND check_in_id = #{checkInId}
AND status = #{status}
AND handler_id = #{handlerId}
ORDER BY created_at DESC

SELECT COUNT(*)
FROM check_in_exception
WHERE status = #{status}
